class Solution {
public:
    int minFlips(int a, int b, int c) {
        int flips = 0;
        for (int i = 0; i < 32; ++i) {
            int ba = (a >> i) & 1;
            int bb = (b >> i) & 1;
            int bc = (c >> i) & 1;
            if (bc == 0) {
                flips += (ba + bb);
            } else {
                if (ba == 0 && bb == 0) flips += 1;
            }
        }
        return flips;
    }
};

class Solution {
    public int minFlips(int a, int b, int c) {
