var minFlips = function(a, b, c) {
    let flips = 0;
    for (let i = 0; i < 32; i++) {
        const ba = (a >> i) & 1;
        const bb = (b >> i) & 1;
        const bc = (c >> i) & 1;
        if (bc === 0) {
            flips += (ba + bb);
        } else {
            if (ba === 0 && bb === 0) flips += 1;
        }
    }
    return flips;
};
